/**
 * Franklin AI — image de partage (app/og.png/route.ts)
 *
 * Le produit repose entièrement sur le partage : c'est son unique canal
 * d'acquisition gratuit. Sans image de prévisualisation, un lien Franklin collé
 * dans WhatsApp ou iMessage s'affiche comme une URL nue, et la mascotte — le seul
 * élément vraiment mémorable de la marque — n'apparaît jamais au moment décisif.
 *
 * L'image est embarquée en base64 plutôt que déposée comme binaire : elle vit
 * ainsi dans le même commit que le code qui la sert. 1200x630, le format attendu
 * par Open Graph.
 */

export const runtime = "nodejs";

const IMAGE =
  "";

export async function GET() {
  return new Response(Buffer.from(IMAGE, "base64"), {
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=31536000, immutable",
    },
  });
}
